using IIoT.FaultDiagnosis.Application.Diagnosis;
using IIoT.FaultDiagnosis.Domain.Entities;
using Microsoft.EntityFrameworkCore;
namespace IIoT.FaultDiagnosis.Infrastructure.Persistence;
public sealed class DiagnosisRepository(FaultDiagnosisDbContext db) : IDiagnosisRepository { public Task<CommunicationRecord?> GetRecordAsync(Guid id,CancellationToken ct)=>db.CommunicationRecords.SingleOrDefaultAsync(x=>x.Id==id,ct); public Task AddAsync(DiagnosisResult r,CancellationToken ct)=>db.DiagnosisResults.AddAsync(r,ct).AsTask(); public async Task<DiagnosisEvaluation?> GetEvaluationAsync(Guid id,CancellationToken ct) { var rows=await (from e in db.Experiments where e.Id==id join r in db.CommunicationRecords on e.Id equals r.ExperimentId join d in db.DiagnosisResults on r.Id equals d.CommunicationRecordId select new { e.ActualFaultType,d.PredictedFaultType }).ToListAsync(ct); if(rows.Count==0 && !await db.Experiments.AnyAsync(e=>e.Id==id,ct)) return null; var correct=rows.Count(x=>x.ActualFaultType==x.PredictedFaultType); return new DiagnosisEvaluation(rows.Count,correct,rows.Count==0?0:(decimal)correct/rows.Count); } public Task SaveChangesAsync(CancellationToken ct)=>db.SaveChangesAsync(ct); }
